<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= html_escape($title); ?></title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@3.34.1/dist/css/tabler-icons.min.css"><style>body{background:#111831;color:#fff}.shell{max-width:850px;margin:auto;padding:30px 16px}.head{background:linear-gradient(135deg,#785126,#8e355a);padding:26px;border-radius:22px}.quest-card{background:#fff;color:#19233d;border-radius:16px;padding:18px;margin-top:14px}.qicon{font-size:38px}.bar{height:9px;background:#e7e1d5;border-radius:9px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,#ef9a3d,#9b4eae)}.claimed{color:#16804b;font-weight:800}</style></head><body><main class="shell"><a class="text-white" href="<?= base_url('belajar/english-quest'); ?>"><i class="ti ti-arrow-left"></i> Peta Dunia</a><section class="head mt-3"><small>ADVENTURER GUILD</small><h1>Side Quests</h1><p>Selesaikan tantangan jangka panjang dan klaim artefak khusus.</p><div>🔥 Streak <?= (int)$profile['streak_days']; ?> hari · ⭐ Reputation <?= (int)$profile['reputation']; ?> · ⚡ Class Energy <?= (int)$profile['class_energy']; ?></div></section><?php if($this->session->flashdata('success')): ?><div class="alert alert-success mt-3"><?= html_escape($this->session->flashdata('success')); ?></div><?php endif; ?><?php if($this->session->flashdata('error')): ?><div class="alert alert-warning mt-3"><?= html_escape($this->session->flashdata('error')); ?></div><?php endif; ?><?php foreach($quests as $q): ?><article class="quest-card"><div class="d-flex gap-3"><div class="qicon"><?= html_escape($q['icon']); ?></div><div class="flex-fill"><div class="d-flex justify-content-between"><h2><?= html_escape($q['title']); ?></h2><b><?= (int)$q['current']; ?>/<?= (int)$q['target']; ?></b></div><p class="text-secondary"><?= html_escape($q['description']); ?></p><div class="bar"><i style="width:<?= min(100,$q['current']/$q['target']*100); ?>%"></i></div><div class="mt-3 d-flex justify-content-between align-items-center"><span>Hadiah: <?= html_escape($q['reward_item_icon'].' '.$q['reward_item_name']); ?></span><?php if($q['is_claimed']): ?><span class="claimed"><i class="ti ti-circle-check"></i> Diklaim</span><?php elseif($q['is_complete']): ?><a class="btn btn-primary" href="<?= base_url('belajar/english-quest/quests/claim/'.$q['id']); ?>">Klaim Hadiah</a><?php else: ?><button class="btn" disabled>Belum Selesai</button><?php endif; ?></div></div></div></article><?php endforeach; ?></main></body></html>
